def _safe_int(val, default):
    try:
        return int(val) if val is not None and not isinstance(val, bool) else default
    except (TypeError, ValueError):
        return default


def _safe_float(val, default):
    try:
        return float(val) if val is not None and not isinstance(val, bool) else default
    except (TypeError, ValueError):
        return default


def _safe_dict(val):
    return dict(val) if isinstance(val, dict) else {}


def load_config():
    global CONFIG_FILE_PATH
    CONFIG_FILE_PATH = get_config_file_path()
    if os.path.isfile(CONFIG_FILE_PATH):
        try:
            with open(CONFIG_FILE_PATH, "r", encoding="utf-8") as f:
                cfg = json.load(f)
                if not isinstance(cfg, dict):
                    raise ValueError("Config root must be JSON object")
                dirty = False
                if not cfg.get("openrouter_fallbacks_default_off_v1"):
                    # One-time migration: turn OpenRouter fallbacks OFF by default
                    cfg["openrouter_allow_fallbacks"] = False
                    cfg["openrouter_fallbacks_default_off_v1"] = True
                    dirty = True
                if dirty:
                    save_config(cfg)
                return cfg
        except Exception:
            pass
    return {
        "connection_mode": "cloud",
        "api_provider": "openrouter",
        "provider_type": "openrouter",
        "api_key": "",
        "endpoint_url": "",
        "openrouter_allow_fallbacks": False,
        "openrouter_fallbacks_default_off_v1": True,
        "colab_url": "https://ваша-ссылка.trycloudflare.com/v1",
        "colab_model": "default",
        "local_engine": "local_lmstudio",
        "local_url": "http://localhost:1234/v1",
        "local_model": "default",
        "model": "google/gemini-2.5-flash",
        "reasoning_effort": "auto",
        "language": "ru",
        "temperature": 0.7,
        "use_temperature": True,
        "top_k": 40,
        "use_top_k": True,
        "top_p": 0.9,
        "use_top_p": True,
        "min_p": 0.0,
        "use_min_p": False,
        "repetition_penalty": 1.0,
        "use_repetition_penalty": False,
        "presence_penalty": 0.0,
        "use_presence_penalty": False,
        "frequency_penalty": 0.0,
        "use_frequency_penalty": False,
        "context_length": 16384,
        "age_instructions_enabled": False,
        "special_situations_enabled": False,
        "max_tokens": 1500,
        "system_prompt": DEFAULT_SYSTEM_PROMPT,
    }


def save_config(cfg):
    global CONFIG_FILE_PATH
    tmp_path = None
    try:
        CONFIG_FILE_PATH = get_config_file_path()
        exe_dir = os.path.dirname(os.path.abspath(sys.executable)) if getattr(sys, 'frozen', False) else os.path.dirname(os.path.abspath(__file__))
        bridge_bin = "ai_bridge.exe" if sys.platform == "win32" else "ai_bridge"
        candidate_bridge = os.path.join(exe_dir, bridge_bin)
        if os.path.isfile(candidate_bridge):
            cfg["bridge_path"] = candidate_bridge
        os.makedirs(os.path.dirname(CONFIG_FILE_PATH), exist_ok=True)
        tmp_path = f"{CONFIG_FILE_PATH}.{os.getpid()}.{threading.get_ident()}.tmp"
        with open(tmp_path, "w", encoding="utf-8") as f:
            json.dump(cfg, f, ensure_ascii=False, indent=2)
        os.replace(tmp_path, CONFIG_FILE_PATH)
        return True
    except Exception as e:
        if tmp_path and os.path.exists(tmp_path):
            try:
                os.remove(tmp_path)
            except Exception:
                pass
        print(f"[ERROR] Save failed: {e}")
        return False


SYNAPSE_MOD_FILES = (
    "Synapse_Balloons.package",
    "Synapse_Balloons.ts4script",
    "Synapse_Interactions.package",
    "Synapse_SimMind.ts4script",
    "Synapse_SocialMessenger.ts4script",
)


def _find_synapse_mod_source_dirs():
    candidates = []
    try:
        base_dir = os.path.dirname(os.path.abspath(sys.executable)) if getattr(sys, "frozen", False) else os.path.dirname(os.path.abspath(__file__))
        cur = base_dir
        for _ in range(5):
            for cand in (os.path.join(cur, "SynapseMod"), cur):
                if os.path.isdir(cand) and cand not in candidates:
                    candidates.append(cand)
            nxt = os.path.dirname(cur)
            if not nxt or nxt == cur:
                break
            cur = nxt
    except Exception:
        pass
    return candidates


def inspect_mods_installation():
    sims4_dir = _get_sims4_root_dir()
    mods_dir = os.path.join(sims4_dir, "Mods")
    options_path = os.path.join(sims4_dir, "Options.ini")

    result = {
        "sims4_dir": sims4_dir,
        "mods_dir": mods_dir,
        "mods_exists": os.path.isdir(mods_dir),
        "found": {fn: [] for fn in SYNAPSE_MOD_FILES},
        "missing": [],
        "too_deep": [],
        "duplicates": [],
        "scripts_disabled": False,
        "mods_disabled": False,
        "has_sources": False,
        "status": "ok",
    }

    if os.path.isfile(options_path):
        try:
            with open(options_path, "r", encoding="utf-8", errors="ignore") as f:
                for line in f:
                    s = line.strip().lower().replace(" ", "")
                    if s.startswith("scriptmodsenabled="):
                        if s.split("=", 1)[1].startswith("0"):
                            result["scripts_disabled"] = True
                    elif s.startswith("modsdisabled="):
                        if s.split("=", 1)[1].startswith("1"):
                            result["mods_disabled"] = True
        except Exception:
            pass

    target_set = {fn.lower(): fn for fn in SYNAPSE_MOD_FILES}
    if result["mods_exists"]:
        for root, _, files in os.walk(mods_dir):
            rel = os.path.relpath(root, mods_dir)
            depth = 0 if rel == "." else len(rel.split(os.sep))
            for fn in files:
                canon = target_set.get(fn.lower())
                if not canon:
                    continue
                full_p = os.path.join(root, fn)
                result["found"][canon].append((full_p, depth, rel))
                if canon.lower().endswith(".ts4script") and depth >= 2:
                    result["too_deep"].append((canon, full_p, depth))

    for fn in SYNAPSE_MOD_FILES:
        locs = result["found"][fn]
        if not locs:
            result["missing"].append(fn)
        elif len(locs) > 1:
            result["duplicates"].append((fn, [p for p, _, _ in locs]))

    # Check if we can source missing/repair files
    source_map = {}
    for src_dir in _find_synapse_mod_source_dirs():
        for fn in SYNAPSE_MOD_FILES:
            fp = os.path.join(src_dir, fn)
            if fn not in source_map and os.path.isfile(fp):
                source_map[fn] = fp
    for fn, locs in result["found"].items():
        if fn not in source_map and locs:
            source_map[fn] = locs[0][0]
    result["source_map"] = source_map
    result["has_sources"] = all(fn in source_map for fn in SYNAPSE_MOD_FILES)

    if not result["mods_exists"] or result["missing"] or result["too_deep"] or result["duplicates"]:
        result["status"] = "error"
    elif result["scripts_disabled"] or result["mods_disabled"]:
        result["status"] = "warn"
    else:
        result["status"] = "ok"
    return result


def repair_mods_installation():
    info = inspect_mods_installation()
    mods_dir = info["mods_dir"]
    target_dir = os.path.join(mods_dir, "SynapseMod")
    os.makedirs(target_dir, exist_ok=True)

    source_map = info.get("source_map", {})
    missing_sources = [fn for fn in SYNAPSE_MOD_FILES if fn not in source_map]
    if missing_sources:
        return False, "Missing source files: " + ", ".join(missing_sources)

    copied = 0
    removed_dups = 0
    for fn in SYNAPSE_MOD_FILES:
        dst = os.path.join(target_dir, fn)
        src = source_map[fn]
        if os.path.abspath(src).lower() != os.path.abspath(dst).lower():
            shutil.copy2(src, dst)
            copied += 1
        elif not os.path.isfile(dst):
            shutil.copy2(src, dst)
            copied += 1

    # Also copy languages folder if present next to source files
    for src_dir in _find_synapse_mod_source_dirs():
        lang_src = os.path.join(src_dir, "languages")
        lang_dst = os.path.join(target_dir, "languages")
        if os.path.isdir(lang_src):
            shutil.copytree(lang_src, lang_dst, dirs_exist_ok=True)
            break

    # Remove misplaced or duplicate Synapse mod files outside Mods/SynapseMod
    target_norm = os.path.normcase(os.path.abspath(target_dir))
    for fn in SYNAPSE_MOD_FILES:
        for old_path, _, _ in info["found"].get(fn, []):
            old_dir = os.path.normcase(os.path.dirname(os.path.abspath(old_path)))
            if old_dir != target_norm and os.path.isfile(old_path):
                try:
                    os.remove(old_path)
                    removed_dups += 1
                except Exception:
                    pass

    return True, f"Installed/repaired into {target_dir} (updated: {copied}, cleaned duplicates/misplaced: {removed_dups})"


SYNAPSE_MIGRATION_FILES = (
    "ai_mod_config.json",
    "ai_sim_lore.json",
    "ai_sim_races.json",
    "ai_world_lore.json",
    "ai_social_memories.json",
    "ai_social_recent_conversations.json",
    "ai_social_dd_settings.json",
    "synapse_simgram_chats.json",
    "synapse_simgram_profiles.json",
    "synapse_sulnet_settings.json",
    "ai_mind_reader.log",
    "ai_social_pc.log",
    "synapse_balloons.log",
)

SYNAPSE_MIGRATION_DIRS = (
    "synapse_simgram_media",
)


def _is_sims4_process_running():
    """Returns True if The Sims 4 game process appears to be running."""
    try:
        if sys.platform == "win32":
            flags = getattr(subprocess, "CREATE_NO_WINDOW", 0x08000000)
            for exe_name in ("TS4_x64.exe", "TS4.exe", "TS4_DX9_x64.exe"):
                res = subprocess.run(
                    ["tasklist", "/NH", "/FI", f"IMAGENAME eq {exe_name}"],
                    capture_output=True,
                    text=True,
                    timeout=3,
                    creationflags=flags,
                )
                if exe_name.lower() in (res.stdout or "").lower():
                    return True
        elif sys.platform == "darwin":
            res = subprocess.run(
                ["pgrep", "-ix", "The Sims 4"],
                capture_output=True,
                text=True,
                timeout=3,
            )
            if res.returncode == 0:
                return True
    except Exception:
        pass
    return False


def _make_bak_path(path):
    """Generates a non-colliding `.bak` backup path next to `path`."""
    cand = f"{path}.bak"
    if not os.path.exists(cand):
        return cand
    ts = datetime.now().strftime("%Y%m%d_%H%M%S")
    cand = f"{path}.{ts}.bak"
    if not os.path.exists(cand):
        return cand
    idx = 2
    while True:
        c2 = f"{path}.{ts}_{idx}.bak"
        if not os.path.exists(c2):
            return c2
        idx += 1


def _rewrite_media_paths_in_obj(obj, src_media_dir, dst_media_dir):
    if isinstance(obj, str):
        if not src_media_dir or not dst_media_dir:
            return obj
        src_clean = os.path.normpath(src_media_dir)
        obj_clean = os.path.normpath(obj)
        src_norm = os.path.normcase(src_clean)
        obj_norm = os.path.normcase(obj_clean)
        if obj_norm.startswith(src_norm + os.sep) or obj_norm.startswith(src_norm + "/"):
            rel = obj_clean[len(src_clean):].lstrip("\\/")
            return os.path.join(dst_media_dir, rel)
        return obj
    if isinstance(obj, list):
        return [_rewrite_media_paths_in_obj(x, src_media_dir, dst_media_dir) for x in obj]
    if isinstance(obj, dict):
        return {k: _rewrite_media_paths_in_obj(v, src_media_dir, dst_media_dir) for k, v in obj.items()}
    return obj


def _merge_list_entries(dst_list, src_list):
    out = list(dst_list)
    seen = set()
    for item in dst_list:
        try:
            seen.add(json.dumps(item, ensure_ascii=False, sort_keys=True))
        except Exception:
            seen.add(repr(item))
    for item in src_list:
        try:
            sig = json.dumps(item, ensure_ascii=False, sort_keys=True)
        except Exception:
            sig = repr(item)
        if sig not in seen:
            seen.add(sig)
            out.append(item)
    return out


def _deep_merge_prefer_target(dst_obj, src_obj):
    if isinstance(dst_obj, dict) and isinstance(src_obj, dict):
        merged = dict(dst_obj)
        for k, sv in src_obj.items():
            if k not in merged or merged[k] is None:
                merged[k] = sv
            else:
                dv = merged[k]
                if isinstance(dv, dict) and isinstance(sv, dict):
                    merged[k] = _deep_merge_prefer_target(dv, sv)
                elif isinstance(dv, list) and isinstance(sv, list):
                    merged[k] = _merge_list_entries(dv, sv)
                elif isinstance(dv, str) and not dv.strip() and isinstance(sv, str) and sv.strip():
                    merged[k] = sv
        return merged
    return dst_obj


def _merge_config_dicts(dst_cfg, src_cfg):
    merged = _deep_merge_prefer_target(dst_cfg, src_cfg)
    # If target config had no API key configured while source config had one, import active provider/model/prompt fields too
    dst_key = str(dst_cfg.get("api_key") or "").strip()
    src_key = str(src_cfg.get("api_key") or "").strip()
    if not dst_key and src_key:
        for k in ("connection_mode", "api_provider", "provider_type", "api_key", "endpoint_url", "model", "colab_url", "colab_model", "local_engine", "local_url", "local_model", "local_api_key", "system_prompt", "language"):
            if src_cfg.get(k):
                merged[k] = src_cfg[k]
    return merged


def _write_json_atomic(target_path, payload):
    os.makedirs(os.path.dirname(target_path), exist_ok=True)
    tmp_path = f"{target_path}.{os.getpid()}.{threading.get_ident()}.tmp"
    try:
        with open(tmp_path, "w", encoding="utf-8") as f:
            json.dump(payload, f, ensure_ascii=False, indent=2)
        os.replace(tmp_path, target_path)
    finally:
        if os.path.exists(tmp_path):
            try:
                os.remove(tmp_path)
            except Exception:
                pass


def inspect_synapse_data_migration():
    """
    Scans alternate 'Electronic Arts/The Sims 4' folders (other than `_get_sims4_root_dir()`)
    for misplaced Synapse config, save data, media, or logs that belong in the real TS4 folder.
    Ignores `.bak` backups and junctions pointing to the same real directory.
    """
    target_dir = _get_sims4_root_dir()
    target_real = _norm_real_key(target_dir)
    sources = []
    total_files = 0
    total_media = 0

    for cand in _get_all_sims4_candidate_dirs():
        if not os.path.isdir(cand):
            continue
        if _norm_real_key(cand) == target_real:
            continue

        found_files = []
        for fn in SYNAPSE_MIGRATION_FILES:
            fp = os.path.join(cand, fn)
            if os.path.isfile(fp):
                found_files.append(fn)

        media_dir = os.path.join(cand, "synapse_simgram_media")
        media_count = 0
        if os.path.isdir(media_dir):
            try:
                for root, _, files in os.walk(media_dir):
                    for fn in files:
                        low = fn.lower()
                        if low.endswith(".bak") or low.endswith(".tmp"):
                            continue
                        media_count += 1
            except Exception:
                media_count = 0

        if found_files or media_count > 0:
            sources.append({
                "source_dir": cand,
                "files": found_files,
                "media_count": media_count,
                "media_dir": media_dir if media_count > 0 else None,
            })
            total_files += len(found_files)
            total_media += media_count

    return {
        "target_dir": target_dir,
        "sources": sources,
        "total_files": total_files,
        "total_media": total_media,
        "needs_migration": bool(sources),
    }


def migrate_synapse_data_to_active_dir(check_game_running=True):
    """
    Safely copies/merges all misplaced Synapse mod files & media into the active TS4 folder,
    then renames the original files/folders in the old location to `.bak` backups in place.
    """
    info = inspect_synapse_data_migration()
    if not info.get("needs_migration"):
        return True, "NOTHING_TO_MIGRATE", info

    if check_game_running and _is_sims4_process_running():
        return False, "GAME_RUNNING", info

    target_dir = info["target_dir"]
    os.makedirs(target_dir, exist_ok=True)
    target_media_dir = os.path.join(target_dir, "synapse_simgram_media")

    migrated_files = []
    merged_files = []
    migrated_media = 0
    bak_entries = []
    errors = []

    for src_entry in info["sources"]:
        src_dir = src_entry["source_dir"]
        src_media_dir = os.path.join(src_dir, "synapse_simgram_media")

        # 1. Copy media files first so rewritten screenshot paths point to valid files
        if src_entry.get("media_dir") and os.path.isdir(src_media_dir):
            os.makedirs(target_media_dir, exist_ok=True)
            media_copy_ok = True
            for root, _, files in os.walk(src_media_dir):
                rel_root = os.path.relpath(root, src_media_dir)
                dst_root = target_media_dir if rel_root == "." else os.path.join(target_media_dir, rel_root)
                os.makedirs(dst_root, exist_ok=True)
                for fn in files:
                    low = fn.lower()
                    if low.endswith(".bak") or low.endswith(".tmp"):
                        continue
                    s_fp = os.path.join(root, fn)
                    d_fp = os.path.join(dst_root, fn)
                    try:
                        need_copy = (not os.path.isfile(d_fp)) or (os.path.getsize(d_fp) == 0 and os.path.getsize(s_fp) > 0)
                        if need_copy:
                            shutil.copy2(s_fp, d_fp)
                            migrated_media += 1
                    except Exception as ex_m:
                        media_copy_ok = False
                        errors.append(f"{s_fp}: {ex_m}")
            if media_copy_ok:
                try:
                    bak_media = _make_bak_path(src_media_dir)
                    os.replace(src_media_dir, bak_media)
                    bak_entries.append(bak_media)
                except Exception as ex_bm:
                    errors.append(f"rename {src_media_dir}: {ex_bm}")

        # 2. Copy or merge JSON / log files and rename originals to .bak
        for fn in src_entry["files"]:
            s_fp = os.path.join(src_dir, fn)
            d_fp = os.path.join(target_dir, fn)
            if not os.path.isfile(s_fp):
                continue
            try:
                is_json = fn.lower().endswith(".json")
                dst_existed = os.path.isfile(d_fp)
                if is_json:
                    src_data = None
                    try:
                        with open(s_fp, "r", encoding="utf-8") as f:
                            src_data = json.load(f)
                    except Exception:
                        src_data = None

                    if isinstance(src_data, dict):
                        src_data = _rewrite_media_paths_in_obj(src_data, src_media_dir, target_media_dir)
                        if dst_existed:
                            dst_data = None
                            try:
                                with open(d_fp, "r", encoding="utf-8") as f:
                                    dst_data = json.load(f)
                            except Exception:
                                dst_data = None
                            if isinstance(dst_data, dict):
                                if fn == "ai_mod_config.json":
                                    final_data = _merge_config_dicts(dst_data, src_data)
                                else:
                                    final_data = _deep_merge_prefer_target(dst_data, src_data)
                                _write_json_atomic(d_fp, final_data)
                                merged_files.append(fn)
                            else:
                                _write_json_atomic(d_fp, src_data)
                                migrated_files.append(fn)
                        else:
                            _write_json_atomic(d_fp, src_data)
                            migrated_files.append(fn)
                    else:
                        if not dst_existed:
                            shutil.copy2(s_fp, d_fp)
                            migrated_files.append(fn)
                else:
                    if not dst_existed:
                        shutil.copy2(s_fp, d_fp)
                        migrated_files.append(fn)

                if os.path.exists(d_fp):
                    bak_fp = _make_bak_path(s_fp)
                    os.replace(s_fp, bak_fp)
                    bak_entries.append(bak_fp)
            except Exception as ex_f:
                errors.append(f"{s_fp}: {ex_f}")

    summary = {
        "target_dir": target_dir,
        "migrated_files": migrated_files,
        "merged_files": merged_files,
        "migrated_media": migrated_media,
        "bak_entries": bak_entries,
        "errors": errors,
    }
    ok = (len(errors) == 0)
    return ok, ("OK" if ok else "; ".join(errors)), summary


def is_bridge_running():
    try:
        with socket.create_connection(("127.0.0.1", BRIDGE_PORT), timeout=0.3):
            return True
    except Exception:
        return False


def resolve_chat_url(base_url: str, api_type: str = "openai") -> str:
    url = (base_url or "").strip().rstrip("/")
    if not url:
        return "https://openrouter.ai/api/v1/chat/completions"
    if api_type == "anthropic":
        if url.endswith("/messages"):
            return url
        if url.endswith("/v1"):
            return f"{url}/messages"
        return f"{url}/v1/messages"
    if url.endswith("/chat/completions"):
        return url
    if "api.perplexity.ai" in url.lower() and not url.endswith("/v1"):
        return f"{url}/chat/completions"
    if any(url.endswith(suffix) for suffix in ["/v1", "/v2", "/v3", "/v4", "/v1beta", "/v1beta/openai", "/compatibility/v1", "/openai"]):
        return f"{url}/chat/completions"
    return f"{url}/v1/chat/completions"


def _format_price_per_m(val: float) -> str:
    """Format token price per 1M tokens accurately without .2f rounding distortion."""
    try:
        v = float(val)
    except Exception:
        return "$0"
    if v <= 0:
        return "$0"
    if v >= 10.0:
        return f"${v:.2f}"
    if v >= 0.01:
        s = f"{v:.4f}"
        while len(s.split(".")[1]) > 2 and s.endswith("0"):
            s = s[:-1]
        return f"${s}"
    s = f"{v:.6f}"
    while len(s.split(".")[1]) > 2 and s.endswith("0"):
        s = s[:-1]
    return f"${s}"


def _resolve_openrouter_endpoint_pricing(pricing: dict):
    """Return (p_in_1m, p_out_1m, discount_pct, is_override_active, has_schedule)."""
    pr = pricing if isinstance(pricing, dict) else {}
    try:
        raw_in = float(pr.get("prompt", 0) or 0) * 1_000_000
        raw_out = float(pr.get("completion", 0) or 0) * 1_000_000
    except Exception:
        raw_in, raw_out = 0.0, 0.0

    p_in, p_out = raw_in, raw_out
    try:
        disc_raw = float(pr.get("discount", 0) or 0)
        discount_pct = int(round(disc_raw * 100)) if 0 < disc_raw < 1 else 0
    except Exception:
        discount_pct = 0

    overrides = pr.get("overrides")
    has_schedule = bool(isinstance(overrides, list) and overrides)
    active_override = False

    if has_schedule:
        now_utc = datetime.now(timezone.utc)
        weekday_name = now_utc.strftime("%A").lower()
        hhmm = now_utc.hour * 100 + now_utc.minute
        for ov in overrides:
            if not isinstance(ov, dict):
                continue
            days = ov.get("utc_days")
            if isinstance(days, list) and days:
                if weekday_name not in [str(d).strip().lower() for d in days]:
                    continue
            has_window = ("utc_start" in ov or "utc_end" in ov)
            if has_window:
                start_hm = int(ov.get("utc_start", 0) or 0)
                end_hm = int(ov.get("utc_end", 0) or 0)
                if start_hm == 0 and end_hm == 0:
                    in_window = True
                elif start_hm < end_hm:
                    in_window = (start_hm <= hhmm < end_hm)
                elif end_hm == 0:
                    in_window = (start_hm <= hhmm < 2400)
                else:
                    in_window = (hhmm >= start_hm or hhmm < end_hm)
                if not in_window:
                    continue
            try:
                ov_in = float(ov.get("prompt", pr.get("prompt", 0)) or 0) * 1_000_000
                ov_out = float(ov.get("completion", pr.get("completion", 0)) or 0) * 1_000_000
                p_in, p_out = ov_in, ov_out
                active_override = (abs(ov_in - raw_in) > 1e-9 or abs(ov_out - raw_out) > 1e-9)
                break
            except Exception:
                continue

    return p_in, p_out, discount_pct, active_override, has_schedule


def _parse_openrouter_endpoints(endpoints: list, is_en: bool = False) -> list:
    """Parse all OpenRouter endpoints without tag/name collisions, keeping tiers and status."""
    parsed = []
    seen_tags = {}
    for idx, ep in enumerate(endpoints or []):
        if not isinstance(ep, dict):
            continue
        pname = (ep.get("provider_name") or ep.get("name") or "").strip()
        if not pname:
            continue
        raw_tag = (ep.get("tag") or "").strip().lower()
        if not raw_tag:
            raw_tag = "-".join(pname.lower().split())

        if raw_tag in seen_tags:
            seen_tags[raw_tag] += 1
            unique_key = f"{raw_tag}#{seen_tags[raw_tag]}"
        else:
            seen_tags[raw_tag] = 1
            unique_key = raw_tag

        p_in, p_out, disc_pct, ov_active, has_sched = _resolve_openrouter_endpoint_pricing(ep.get("pricing"))
        q = (ep.get("quantization") or "").strip()
        tier = (ep.get("service_tier") or "").strip()
        try:
            status = int(ep.get("status", 0) or 0)
        except Exception:
            status = 0
        uptime = ep.get("uptime_last_30m")
        lat_ms = ep.get("latency_last_30m")
        thr = ep.get("throughput_last_30m")

        if p_in == 0 and p_out == 0:
            price_str = "Free" if is_en else "Бесплатно"
        else:
            price_str = f"{_format_price_per_m(p_in)} / {_format_price_per_m(p_out)}"

        badges = []
        if tier:
            badges.append(tier)
        if q and q.lower() != "unknown":
            badges.append(q)
        skip_tokens = {x.lower() for x in (tier, q) if x}
        for tp in raw_tag.split("/")[1:]:
            if tp and tp.lower() not in skip_tokens:
                badges.append(tp)

        parsed.append({
            "key": unique_key,
            "tag": raw_tag,
            "provider_name": pname,
            "base_slug": raw_tag.split("/")[0],
            "p_in": p_in,
            "p_out": p_out,
            "discount_pct": disc_pct,
            "override_active": ov_active,
            "has_schedule": has_sched,
            "quantization": q,
            "service_tier": tier,
            "status": status,
            "uptime": uptime,
            "latency_ms": lat_ms,
            "throughput": thr,
            "price_str": price_str,
            "badges": badges,
            "api_idx": idx,
        })
    return parsed


class PresetCreateModal(ctk.CTkToplevel):
    def __init__(self, master, on_save_callback):
        super().__init__(master)
        self.master_app = master
        self.on_save_callback = on_save_callback
        i18n = getattr(master, "i18n", None)
        is_en = bool(i18n and getattr(i18n, "current_code", "") == "en")
        self.is_en = is_en

        self.title("Create Sampling Preset" if is_en else "Создать пресет настроек")
        self.geometry("450x240")
        self.resizable(False, False)
        self.configure(fg_color=("#1e293b", "#0f172a"))
        self.transient(master)
        self.grab_set()

        try:
            pw = master.winfo_width()
            ph = master.winfo_height()
            px = master.winfo_rootx()
            py = master.winfo_rooty()
            x = px + max(0, (pw - 450) // 2)
            y = py + max(0, (ph - 240) // 2)
            self.geometry(f"+{x}+{y}")
        except Exception:
            pass

        head_lbl = ctk.CTkLabel(
            self,
            text="⚡ New Sampling Preset" if is_en else "⚡ Новый пресет параметров (Sampling)",
            font=ctk.CTkFont(size=14, weight="bold"),
            text_color=("#38bdf8", "#60a5fa"),
        )
        head_lbl.pack(padx=20, pady=(18, 6), anchor="w")

        info_lbl = ctk.CTkLabel(
            self,
            text=(
                "Current slider values (temperature, Top-K, Top-P, Min-P,\npenalties and reasoning mode) will be saved under this name:"
                if is_en else
                "Текущие значения ползунков (температура, Top-K, Top-P, Min-P,\nштрафы и режим рассуждений) будут сохранены под этим именем:"
            ),
            font=ctk.CTkFont(size=11),
            text_color="#94a3b8",
            justify="left",
        )
        info_lbl.pack(padx=20, pady=(0, 14), anchor="w")

        self.name_entry = ctk.CTkEntry(
            self,
            placeholder_text="e.g.: My Qwen 2.5 or Gemma Roleplay" if is_en else "Например: Мой Qwen 2.5 или Gemma Roleplay",
            height=34,
            font=ctk.CTkFont(size=12),
        )
        self.name_entry.pack(fill="x", padx=20, pady=(0, 18))
        self.name_entry.focus_set()

        btn_row = ctk.CTkFrame(self, fg_color="transparent")
        btn_row.pack(fill="x", padx=20, pady=(0, 16))

        cancel_btn = ctk.CTkButton(
            btn_row,
            text="Cancel" if is_en else "Отмена",
            font=ctk.CTkFont(size=12),
            fg_color="#334155",
            hover_color="#475569",
            width=100,
            height=32,
            command=self.destroy,
        )
        cancel_btn.pack(side="left")

        save_btn = ctk.CTkButton(
            btn_row,
            text="💾 Save" if is_en else "💾 Сохранить",
            font=ctk.CTkFont(size=12, weight="bold"),
            fg_color="#0284c7",
            hover_color="#0369a1",
            width=130,
            height=32,
            command=self._on_confirm,
        )
        save_btn.pack(side="right")

        self.bind("<Return>", lambda e: self._on_confirm())
        self.bind("<Escape>", lambda e: self.destroy())

    def _on_confirm(self):
        name = self.name_entry.get().strip()
        if not name:
            warn_title = "Error" if getattr(self, "is_en", False) else "Ошибка"
            warn_msg = "Enter a preset name!" if getattr(self, "is_en", False) else "Введите название пресета!"
            messagebox.showwarning(warn_title, warn_msg, parent=self)
            return
        self.on_save_callback(name)
        self.destroy()


